import assert from 'node:assert/strict';
import {W04EvidenceDomain,createEvidenceCompareProvider} from '../../../adapters/evidence/domain.js';
import {W04ReviewDomain,createReviewsCompareProvider} from '../../../adapters/reviews/domain.js';
import {AnalyticalCompareOwner} from '../../../foundation/analytical/compare.js';
const immutableRevisionCore=revision=>{const {lifecycle,...core}=revision;return core;};

const e=new W04EvidenceDomain();
const imported=e.importEvidence({id:'candidate-import',revisionId:'candidate-import-r0',title:'Imported artifact',sourceBytesAvailable:true,schemaValid:true,digest:'sha256:aaaaaaaaaaaaaaaa',sourceId:'artifact-1',sourceRevision:'artifact-r1',actor:'owner:local',criterionRefs:['criteria:v4#integrity'],admissionAuthority:{available:false,proofRef:null}});
assert.equal(imported.ok,true);assert.equal(imported.canonicalEvidenceCreated,false);assert.equal(e.inspect('candidate-import').status,'CANDIDATE');assert.equal(e.lineage.has('candidate-import'),false);
assert.equal(e.admit('candidate-import').code,'CANDIDATE_NOT_SUBMITTED_FOR_INTAKE');assert.equal(e.evidenceRevisions.some(r=>r.evidenceId==='candidate-import'),false);assert.equal(e.markCandidateValidated('candidate-import',{validator:'intake:test',validationProofRef:'validation:test:v1'}).ok,true);assert.equal(e.submitCandidate('candidate-import',{expectedCandidateRevision:e.inspect('candidate-import').candidateRevision}).ok,true);assert.equal(e.admit('candidate-import',{expectedPriorRevisionId:null}).code,'ADMISSION_AUTHORITY_UNAVAILABLE');e.setAdmissionAuthority('candidate-import',true,'authority:admit:test');
const admitted=e.admit('candidate-import',{expectedPriorRevisionId:null,actor:'reviewer:evidence-admission'});assert.equal(admitted.ok,true);assert.equal(admitted.revision.previousRevisionRef,null);assert.equal(e.evidenceRevisions.filter(r=>r.evidenceId==='candidate-import').length,1);assert.equal(e.admit('candidate-import').code,'CANDIDATE_ALREADY_ADMITTED');assert.equal(e.evidenceRevisions.filter(r=>r.evidenceId==='candidate-import').length,1);
const r1=e.inspectRevision('candidate-import',admitted.revision.revisionId),r1Bytes=JSON.stringify(immutableRevisionCore(r1));
const amendment=e.amend('candidate-import',{expectedBaseRevisionId:r1.revisionId,candidateId:'candidate-import-amend-1',notes:'Clarify context only',reason:'Correction of same governed claim',admissionAuthority:{available:true,proofRef:'authority:admit:test'}});assert.equal(amendment.ok,true);assert.equal(JSON.stringify(immutableRevisionCore(e.inspectRevision('candidate-import',r1.revisionId))),r1Bytes);assert.equal(e.markCandidateValidated('candidate-import-amend-1',{validator:'intake:test',validationProofRef:'validation:test:amend1'}).ok,true);assert.equal(e.submitCandidate('candidate-import-amend-1',{expectedCandidateRevision:e.inspect('candidate-import-amend-1').candidateRevision}).ok,true);assert.equal(e.admit('candidate-import-amend-1',{expectedPriorRevisionId:'wrong'}).code,'STALE_EXPECTED_EVIDENCE_REVISION');
const admitted2=e.admit('candidate-import-amend-1',{expectedPriorRevisionId:r1.revisionId,actor:'reviewer:evidence-admission'});assert.equal(admitted2.ok,true);assert.equal(admitted2.revision.previousRevisionRef,r1.revisionId);assert.equal(e.evidenceRevisions.filter(r=>r.evidenceId==='candidate-import').length,2);assert.equal(JSON.stringify(immutableRevisionCore(e.inspectRevision('candidate-import',r1.revisionId))),r1Bytes);
assert.equal(e.amend('candidate-import',{expectedBaseRevisionId:admitted2.revision.revisionId,digest:'sha256:rewrite'}).code,'SOURCE_FACT_MUTATION_FORBIDDEN');
const betaRevision=e.inspect('ev-beta').currentRevision, betaBytes=JSON.stringify(immutableRevisionCore(betaRevision));assert.equal(e.sourceChoice('ev-beta','retain').code,'RETAIN_REASON_REQUIRED');const retained=e.sourceChoice('ev-beta',{choice:'retain',reason:'Pinned historical source remains the reviewed basis'});assert.equal(retained.ok,true);assert.equal(retained.evidenceRevisionMutated,false);assert.equal(JSON.stringify(immutableRevisionCore(e.inspectRevision('ev-beta',betaRevision.revisionId))),betaBytes);
const alpha=e.inspect('ev-alpha');assert.equal(alpha.reviewProjection.state,'NOT_APPLICABLE');assert.equal(alpha.reviewStatus,null);assert.equal(alpha.effectiveDecision,null);

const r=new W04ReviewDomain(undefined,{evidenceResolver:ref=>e.resolveReviewableEvidenceRef(ref)});const requested=r.review('review-new',{action:'request',evidenceRefs:['candidate-import@'+admitted2.revision.revisionId],criteriaRefs:['criteria:v4#integrity'],reviewer:{identity:'reviewer:new',permissionProofRef:'perm:new:v1',authorityAvailable:true,assignmentPermissionAvailable:false}});assert.equal(requested.ok,true);assert.equal(requested.record.state,'REQUESTED');assert.equal(r.review('review-new',{action:'assign'}).code,'ASSIGNMENT_PERMISSION_UNAVAILABLE');r.setAssignmentPermission('review-new',true);assert.equal(r.review('review-new',{action:'assign'}).record.state,'ASSIGNED');const decidedBefore=r.inspect('review-1'),effectiveBefore=decidedBefore.effectiveDecisionId,historyBefore=JSON.stringify(decidedBefore.decisionHistory),review1Before=JSON.stringify(decidedBefore);const reopened=r.review('review-1',{action:'rereview',newReviewId:'review-1-rereview'});assert.equal(reopened.ok,true);assert.equal(reopened.record.state,'REQUESTED');assert.equal(reopened.record.previousReviewRef,'review-1');assert.equal(reopened.record.priorDecisionRef,effectiveBefore);assert.equal(JSON.stringify(r.inspect('review-1')),review1Before);assert.equal(JSON.stringify(r.inspect('review-1').decisionHistory),historyBefore);
const beforeFindingDecision=r.inspect('review-2').effectiveDecisionId;assert.equal(r.finding('review-2',{findingId:'bad-scope',text:'Wrong scope',criterionRef:'criteria:v9#other',state:'NOT_SATISFIED'}).code,'CRITERION_OUTSIDE_PINNED_SCOPE');const finding=r.finding('review-2',{findingId:'f-good',text:'Pinned provenance criterion assessed',criterionRef:'criteria:v4#integrity',state:'SATISFIED'});assert.equal(finding.ok,true);assert.equal(r.inspect('review-2').effectiveDecisionId,beforeFindingDecision);const oos=r.finding('review-2',{findingId:'f-oos',text:'Observed unrelated issue',criterionRef:'criteria:v9#other',scopeDisposition:'OUT_OF_SCOPE',outOfScopeReason:'Not part of pinned request',state:'NOT_ASSESSABLE'});assert.equal(oos.ok,true);
r.setAuthority('review-2',false);assert.equal(r.supersede('review-2',{expectedDecisionId:null,newDecision:{decisionId:'decision-x',outcome:'ACCEPT'}}).code,'REVIEWER_AUTHORITY_UNAVAILABLE');r.setAuthority('review-2',true);assert.equal(r.review('review-2',{action:'ready'}).record.state,'READY_FOR_DECISION');
const central=new AnalyticalCompareOwner(),reviewProvider=createReviewsCompareProvider(r);assert.equal(r.compare('review-2',{provider:reviewProvider,left:{id:'review-1',revisionId:r.inspect('review-1').revisionId},right:{id:'review-2',revisionId:r.inspect('review-2').revisionId}}).code,'CENTRAL_ANALYTICAL_COMPARE_REQUIRED');const pinnedBefore=JSON.stringify({evidenceRefs:r.inspect('review-2').evidenceRefs,criteriaRefs:r.inspect('review-2').criteriaRefs,effectiveDecisionId:r.inspect('review-2').effectiveDecisionId});const compared=r.compare('review-2',{compareOwner:central,provider:reviewProvider,left:{id:'review-1',revisionId:r.inspect('review-1').revisionId},right:{id:'review-2',revisionId:r.inspect('review-2').revisionId},sessionId:'s14-review-compare'});assert.equal(compared.ok,true);assert.equal(compared.basisPreserved,true);assert.equal(JSON.stringify({evidenceRefs:r.inspect('review-2').evidenceRefs,criteriaRefs:r.inspect('review-2').criteriaRefs,effectiveDecisionId:r.inspect('review-2').effectiveDecisionId}),pinnedBefore);
assert.equal(r.supersede('review-2',{expectedDecisionId:'wrong',newDecision:{decisionId:'decision-18',outcome:'ACCEPT'},correctionReason:'Correction'}).code,'STALE_EXPECTED_DECISION');const oldDecision=r.inspect('review-2').effectiveDecisionId;const superseded=r.supersede('review-2',{expectedDecisionId:oldDecision,newDecision:{decisionId:'decision-18',outcome:'ACCEPT'},correctionReason:'New formal review corrected limitations'});assert.equal(superseded.ok,true);assert.equal(superseded.priorDecisionRetained,true);assert.equal(r.inspect('review-2').decisionHistory.some(d=>d.decisionId===oldDecision),true);assert.equal(r.inspect('review-2').decision.supersedesDecisionRef,oldDecision);

const withdrawn=e.sourceChoice('ev-beta',{choice:'withdraw',reason:'Source retired'});assert.equal(withdrawn.ok,true);assert.equal(e.inspect('ev-beta').lineage.lifecycle,'WITHDRAWN');assert.equal(JSON.stringify(immutableRevisionCore(e.inspectRevision('ev-beta',betaRevision.revisionId))),betaBytes);
const evidenceCompareOwner=new AnalyticalCompareOwner(),evidenceProvider=createEvidenceCompareProvider(e);evidenceCompareOwner.registerProvider(evidenceProvider);const evidencePair=evidenceCompareOwner.createPair({left:{providerId:evidenceProvider.descriptor().providerId,ref:{id:'candidate-import',revisionId:r1.revisionId}},right:{providerId:evidenceProvider.descriptor().providerId,ref:{id:'candidate-import',revisionId:admitted2.revision.revisionId}}});assert.notEqual(evidenceCompareOwner.comparePair(evidencePair).state,'ERROR');
console.log(JSON.stringify({pass:true,lane:'S14_W04_EVIDENCE_REVIEWS',evidenceRevisions:e.evidenceRevisions.length,reviewDecisionHistory:r.inspect('review-1').decisionHistory.length,centralCompareOwner:central.owner}));
